// Phase 3: Consolidate final notification status
// Exactly 1 of 4 paths feeds into this node per execution:
// 1. P3 Notify Success (Slack worked)
// 2. P3 Email Success (Slack failed, email worked)  
// 3. P3 Both Failed (both failed)
// 4. Direct from Route & Notify (no notification needed)

const input = $input.first().json;

// If this came from a P3 status node, it already has updated notification_status
// If it came directly from Route & Notify (no-notification path), use as-is
return [{ json: input }];

// ============================================================
// NEXUS Stage 5: Route & Notify — Phase 3 (Production)
// PRD S3.1 Stage 5: Notification with fallback chain
// RED/HOT: Slack + email. If Slack fails → email fallback.
// If both fail → error sheet + retry queue.
// AMBER/WARM: log to review queue. GREEN/COLD: auto-close.
// ============================================================

const scoreOutput = $('S3S4 Score and Classify').first().json;
const notificationTargetsRaw = $('Load Notification_Targets').all();

// Phase 3: Check if Notification_Targets Sheets read failed
const ntErrors = [];
let notificationTargets = [];

if (!notificationTargetsRaw || notificationTargetsRaw.length === 0) {
  ntErrors.push('Notification_Targets: returned 0 rows');
} else if (notificationTargetsRaw[0].error || (notificationTargetsRaw[0].json && notificationTargetsRaw[0].json.error)) {
  ntErrors.push('Notification_Targets: Sheets read failed');
} else {
  notificationTargets = notificationTargetsRaw.map(i => i.json);
}

const tier = scoreOutput.tier;
const totalScore = scoreOutput.total_score;
const rulesTriggered = scoreOutput.rules_triggered;
const configPack = scoreOutput.config_pack;
const payload = scoreOutput.payload;

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const itemId = generateUUID();
const logId = generateUUID();

const target = notificationTargets.find(t => 
  t.tier_name === tier && t.config_pack === configPack
);

let action, status, notificationStatus, notificationAction;

if (tier === 'RED' || tier === 'HOT') {
  action = 'escalate';
  status = 'open';
  // Phase 3: actual notification routing
  if (target && target.slack_channel) {
    notificationAction = 'send_slack';
    notificationStatus = 'pending_slack';
  } else if (target && target.email_list) {
    notificationAction = 'send_email';
    notificationStatus = 'pending_email';
  } else {
    // No target config found — log error
    notificationAction = 'no_target';
    notificationStatus = 'error_no_target';
  }
} else if (tier === 'AMBER' || tier === 'WARM') {
  action = 'review';
  status = 'open';
  notificationAction = 'none';
  notificationStatus = 'not_required';
} else if (tier === 'GREEN' || tier === 'COLD') {
  action = 'auto_close';
  status = 'closed';
  notificationAction = 'none';
  notificationStatus = 'not_required';
} else {
  action = 'review';
  status = 'open';
  notificationAction = 'none';
  notificationStatus = 'not_required';
}

// If Notification_Targets Sheets failed, override to error
if (ntErrors.length > 0 && (tier === 'RED' || tier === 'HOT')) {
  notificationAction = 'error_sheets_failed';
  notificationStatus = 'error_config_unavailable';
}

const notificationMessage = action === 'escalate'
  ? `[${configPack.toUpperCase()}] ${tier} ALERT | Score: ${totalScore} | Rules: ${rulesTriggered.join(', ')} | Item: ${itemId}`
  : '';

const payloadSummary = JSON.stringify(payload).substring(0, 500);
const timestamp = new Date().toISOString();
const auditDetails = `Score: ${totalScore} | Tier: ${tier} | Rules: ${rulesTriggered.join(', ')} | Action: ${action} | Notification: ${notificationStatus}`;

return [{
  json: {
    item_id: itemId,
    config_pack: configPack,
    payload_summary: payloadSummary,
    total_score: totalScore,
    tier: tier,
    rules_triggered: rulesTriggered.join(', '),
    status: status,
    notification_status: notificationStatus,
    notification_action: notificationAction,
    sla_breaches: 0,
    created_at: timestamp,
    acknowledged_at: '',
    log_id: logId,
    event_type: 'scored',
    details: auditDetails,
    action: action,
    notification_message: notificationMessage,
    slack_channel: target ? (target.slack_channel || '') : '',
    email_list: target ? (target.email_list || '') : '',
    escalation_contact: target ? (target.escalation_contact || '') : '',
    nt_errors: ntErrors
  }
}];

// S3 — SCORING ENGINE + S4 — CLASSIFY
// PRD S3.1 Stage 3: Loop through active rules, evaluate condition, sum weights.
// PRD S3.1 Stage 3 Error: If single rule fails, skip rule, log warning, continue.
// Phase 3: Added Sheets error detection (PRD S3.1 Stage 2 Error)

// ============================================================
// PHASE 3: CHECK IF SHEETS READS FAILED
// PRD S3.1 Stage 2: If Sheets unavailable → log error, return HTTP 503
// ============================================================
const rulesRaw = $('S2 Load Scoring Rules').all();
const thresholdsRaw = $('S2 Load Tier Thresholds').all();

// Detect Sheets errors — when Continue On Fail fires, the item
// has an 'error' property or the json contains error metadata
const sheetsErrors = [];

function hasSheetsError(items, sheetName) {
  if (!items || items.length === 0) {
    sheetsErrors.push(`${sheetName}: returned 0 rows (empty or unavailable)`);
    return true;
  }
  const first = items[0];
  if (first.error) {
    sheetsErrors.push(`${sheetName}: ${first.error.message || JSON.stringify(first.error)}`);
    return true;
  }
  // n8n Continue On Fail sometimes wraps error in json
  if (first.json && first.json.error) {
    sheetsErrors.push(`${sheetName}: ${first.json.error.message || first.json.error}`);
    return true;
  }
  return false;
}

hasSheetsError(rulesRaw, 'Scoring_Rules');
hasSheetsError(thresholdsRaw, 'Tier_Thresholds');

if (sheetsErrors.length > 0) {
  return [{
    json: {
      sheets_error: true,
      error: 'SHEETS_UNAVAILABLE',
      error_details: sheetsErrors,
      message: `Google Sheets config unavailable: ${sheetsErrors.join('; ')}`,
      timestamp: new Date().toISOString()
    }
  }];
}

// ============================================================
// SCORING (unchanged logic from Phase 2)
// ============================================================
const validationOutput = $('S1 IF Valid').first().json;
const payload = validationOutput.payload;
const configPack = validationOutput.config_pack;

const allRules = rulesRaw.map(i => i.json);
const allThresholds = thresholdsRaw.map(i => i.json);

// Filter rules by config_pack and active status
const activeRules = allRules.filter(r => 
  r.config_pack === configPack && 
  String(r.active).toUpperCase() === 'TRUE'
);

// Filter thresholds by config_pack
const thresholds = allThresholds.filter(t => t.config_pack === configPack);

let totalScore = 0;
const rulesTriggered = [];
const ruleResults = [];
const warnings = [];

for (const rule of activeRules) {
  try {
    const fieldValue = payload[rule.field_name];
    const ruleValue = rule.value;
    const operator = rule.operator;
    const weight = Number(rule.weight);

    let matched = false;

    const fieldStr = String(fieldValue || '').toLowerCase().trim();
    const ruleStr = String(ruleValue || '').toLowerCase().trim();
    const fieldNum = Number(fieldValue);
    const ruleNum = Number(ruleValue);

    switch (operator) {
      case 'equals':
        matched = fieldStr === ruleStr;
        break;
      case 'not_equals':
        matched = fieldStr !== ruleStr;
        break;
      case 'greater_than':
        matched = !isNaN(fieldNum) && !isNaN(ruleNum) && fieldNum > ruleNum;
        break;
      case 'less_than':
        matched = !isNaN(fieldNum) && !isNaN(ruleNum) && fieldNum < ruleNum;
        break;
      case 'greater_equal':
        matched = !isNaN(fieldNum) && !isNaN(ruleNum) && fieldNum >= ruleNum;
        break;
      case 'less_equal':
        matched = !isNaN(fieldNum) && !isNaN(ruleNum) && fieldNum <= ruleNum;
        break;
      case 'contains':
        matched = fieldStr.includes(ruleStr);
        break;
      case 'not_contains':
        matched = !fieldStr.includes(ruleStr);
        break;
      case 'exists':
        matched = fieldValue !== undefined && fieldValue !== null && fieldValue !== '';
        break;
      case 'not_exists':
        matched = fieldValue === undefined || fieldValue === null || fieldValue === '';
        break;
      default:
        warnings.push(`Rule ${rule.rule_id}: unknown operator '${operator}' — skipped`);
        continue;
    }

    ruleResults.push({
      rule_id: rule.rule_id,
      field_name: rule.field_name,
      operator: operator,
      expected: ruleValue,
      actual: fieldValue,
      matched: matched,
      weight: matched ? weight : 0
    });

    if (matched) {
      totalScore += weight;
      rulesTriggered.push(rule.rule_id);
    }

  } catch (err) {
    // PRD S3.1 Stage 3 Error: skip rule, log warning, continue
    warnings.push(`Rule ${rule.rule_id}: execution error — ${err.message} — skipped`);
  }
}

// S4 — CLASSIFY
let assignedTier = null;
let tierAction = null;
let tierChannel = null;

const sortedThresholds = thresholds.sort((a, b) => Number(b.min_score) - Number(a.min_score));

for (const t of sortedThresholds) {
  const minScore = Number(t.min_score);
  const maxScore = Number(t.max_score);

  if (totalScore >= minScore && totalScore <= maxScore) {
    assignedTier = t.tier_name;
    tierAction = t.action;
    tierChannel = t.notification_channel;
    break;
  }
}

if (!assignedTier) {
  assignedTier = 'AMBER';
  tierAction = 'review';
  tierChannel = 'email';
  warnings.push(`No threshold matched score ${totalScore} — defaulted to AMBER`);
}

return [{
  json: {
    sheets_error: false,
    total_score: totalScore,
    tier: assignedTier,
    action: tierAction,
    notification_channel: tierChannel,
    rules_triggered: rulesTriggered,
    rules_triggered_csv: rulesTriggered.join(', '),
    rules_evaluated: activeRules.length,
    rules_matched: rulesTriggered.length,
    rule_results: ruleResults,
    warnings: warnings,
    config_pack: configPack,
    payload: payload,
    scored_at: new Date().toISOString()
  }
}];

// S1 — VALIDATE REQUIRED FIELDS
// PRD S3.1 Stage 1: Returns HTTP 400 with missing field list if validation fails.

const item = $input.first().json;
const body = item.body || item;

// Required fields for alert_triage config pack
const requiredFields = ['alert_id', 'severity', 'source', 'description'];

const missingFields = requiredFields.filter(f => {
  const val = body[f];
  return val === undefined || val === null || val === '';
});

if (missingFields.length > 0) {
  return [{
    json: {
      valid: false,
      error: 'VALIDATION_FAILED',
      missing_fields: missingFields,
      message: `Missing required fields: ${missingFields.join(', ')}`,
      received_fields: Object.keys(body)
    }
  }];
}

// Pass through validated payload
return [{
  json: {
    valid: true,
    payload: body,
    config_pack: body.config_pack || 'alert_triage',
    received_at: new Date().toISOString()
  }
}];
